using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["serviceName"] = "ConfigMcpServer",
        ["version"] = "1.0.0",
        ["environment"] = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
        ["features"] = new Dictionary<string, bool>
        {
            ["enableCaching"] = true,
            ["enableMetrics"] = true,
            ["enableDetailedErrors"] = false
        }
    };

    [McpServerResource(UriTemplate = "config://app", Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON")]
    public static string GetAppConfig() =>
        JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(UriTemplate = "config://environment", Name = "Environment Info",
        MimeType = "application/json"),
     Description("Returns runtime environment details")]
    public static string GetEnvironmentInfo() =>
        JsonSerializer.Serialize(new
        {
            machineName = Environment.MachineName,
            osVersion = Environment.OSVersion.ToString(),
            dotnetVersion = Environment.Version.ToString(),
            processorCount = Environment.ProcessorCount
        }, new JsonSerializerOptions { WriteIndented = true });
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Look up a configuration value by key name")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g., 'serviceName', 'version')")] string key)
    {
        var config = new Dictionary<string, string>
        {
            ["serviceName"] = "ConfigMcpServer",
            ["version"] = "1.0.0",
            ["maxConnections"] = "100",
            ["timeoutSeconds"] = "30"
        };

        return config.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }

    [McpServerTool, Description("List all available configuration keys")]
    public static string ListConfigKeys()
    {
        var keys = new[] { "serviceName", "version", "maxConnections", "timeoutSeconds" };
        return $"Available keys: {string.Join(", ", keys)}";
    }
}

